INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9973, 43360, 'tt0045034', NULL, 'Le Plaisir', 'Le Plaisir', 'movie', 1952, 'https://image.tmdb.org/t/p/w500/qxJAam675KDRIrT5KMYMOMVHBqQ.jpg', 'https://image.tmdb.org/t/p/original/ceVcrZeak4gfbtGUnAUpWIzeiFR.jpg', 'Three stories about the pleasure. The first one is about a man hiding his age behind a mask to keep going to balls and fancying women - pleasure and youth. Then comes the long tale of Mme Tellier taking her girls (whores) to the country for attending her niece''s communion - pleasure and purity. And lastly, Jean the painter falling in love with his model - pleasure and death.', NULL, NULL, 1.814, 7.486, 0, 10.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
