INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9975, 11533, 'tt0057197', NULL, 'Jason and the Argonauts', 'Jason and the Argonauts', 'movie', 1963, 'https://image.tmdb.org/t/p/w500/xHVxIgqD5CxlOI5GHxvVSt5Zh5Y.jpg', 'https://image.tmdb.org/t/p/original/xdefSJpYARFdW4jPhPsuvUlmt2M.jpg', 'Jason, a fearless sailor and explorer, returns to his home land of Thessaly after a long voyage to claim his rightful throne. He learns, however, that he must first find the magical Golden Fleece. To do so, he must embark on an epic quest fraught with fantastic monsters and terrible perils.', NULL, NULL, 5.8696, 7.2, 0, 2.24, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9976, 1725, 'tt0055614', NULL, 'West Side Story', 'West Side Story', 'movie', 1961, 'https://image.tmdb.org/t/p/w500/nzCMu6D5q60i2bVrIQ0DxlRSgCZ.jpg', 'https://image.tmdb.org/t/p/original/bkahbHkwBSbIDtTm667Tu1ba2bu.jpg', 'In Manhattan’s Upper West Side, rival gangs of Polish-Americans and newly arrived Puerto Ricans clash for control of the neighborhood, even as two young members from opposite sides fall dangerously in love.', NULL, NULL, 7.5405, 7.223, 0, 8.04, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9977, 10236, 'tt0070903', NULL, 'The Way We Were', 'The Way We Were', 'movie', 1973, 'https://image.tmdb.org/t/p/w500/o5x563ze56iI4iNsCBxTnDkt28i.jpg', 'https://image.tmdb.org/t/p/original/7mRpaVetpIde0f3Ebk2ipCAqDls.jpg', 'Opposites attract when, during their college days, Katie Morosky, a politically active Jew, meets Hubbell Gardiner, a feckless WASP. Years later, in the wake of World War II, they meet once again and, despite their obvious differences, attempt to make their love for each other work.', NULL, NULL, 5.8538, 6.981, 0, 10.52, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9978, 18317, 'tt0103129', NULL, 'Truly Madly Deeply', 'Truly Madly Deeply', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/jjLEXLTXfJPYtl31knRS8bjclf0.jpg', 'https://image.tmdb.org/t/p/original/GFi1vzXUncFnxfUITfxVBDv8N4.jpg', 'Nina is totally heartbroken at the death of her boyfriend Jamie, but is even more unprepared for his return as a ghost. At first it''s almost as good as it used to be – hey, even the rats that infested her house have disappeared. But Jamie starts bringing ghostly friends home and behaving more and more oddly.', NULL, NULL, 1.9434, 6.9, 0, 8.02, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
