INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9980, 1159019, 'tt0283465', NULL, 'Marilyn Hotchkiss'' Ballroom Dancing and Charm School', 'Marilyn Hotchkiss'' Ballroom Dancing and Charm School', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/pM6QSTBy3CwLduuuT7ALOtwBa4b.jpg', NULL, 'Worse than having your glove stolen, worse than Chinese water torture, even worse than the earth spinning off its axis and careening into Mars, your mom enrolls you in Marilyn Hotchkiss'' program. Not only do we have to wear a tie and jacket, but you have to be polite... and dance... with girls! What Steve and Peter didn''t know was that this was to become the biggest day in their lives, because, for the first time, they were about to like girls...', NULL, NULL, 0.686, 7.5, 0, 7.52, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
