INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9985, 72478, 'tt1808454', NULL, 'Suicide Room', 'Sala samobójców', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/24a6wmwFr8AicQaBdK9LSEPahgb.jpg', 'https://image.tmdb.org/t/p/original/zGNLkZYzFrBvROL2g6UNJsfnA8h.jpg', 'Moody, dark and handsome Dominik is terrorized at school after video footage of his drunken kiss with classmate Aleksandr goes viral. Grappling with public humiliation, Dominik seeks solace in an avatar based ''suicide room'' where the pink-haired rebel Sylwia consoles him.', NULL, NULL, 3.0437, 7.251, 0, 8.0125, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9986, 282035, 'tt2345759', NULL, 'The Mummy', 'The Mummy', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/zxkY8byBnCsXodEYpK8tmwEGXBI.jpg', 'https://image.tmdb.org/t/p/original/i4ZougHEyBAboDpi6jsaTUDTjUl.jpg', 'Though safely entombed in a crypt deep beneath the unforgiving desert, an ancient queen whose destiny was unjustly taken from her is awakened in our current day, bringing with her malevolence grown over millennia, and terrors that defy human comprehension.', NULL, NULL, 14.113, 5.519, 0, 1.02, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9987, 238589, 'tt2395199', NULL, 'Enemies Closer', 'Enemies Closer', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/5njeDzYgcFV8wyVnytKPc3U62Cc.jpg', 'https://image.tmdb.org/t/p/original/cM5zEPXTudPjjcYwjzFcIdxpIsp.jpg', 'After a major shipment of drugs goes missing on the US-Canadian border, forest ranger and former Navy SEAL Henry is plunged into survival mode when the drug cartel forces him to help retrieve the downed package. Trapped in the wilderness with no communication to the outside world, Henry finds himself face to face with Clay, a man with a personal vendetta against Henry who has returned for retribution. Now, the two mortal enemies must make a choice: put aside their past and work together, or die alone at the hands of the drug runners, a ruthless gang who will stop at nothing to retrieve their lost cargo.', NULL, NULL, 3.4523, 5.422, 0, 1.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9988, 136797, 'tt2369135', NULL, 'Need for Speed', 'Need for Speed', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/4ktdbrhCnAoDGLW36afjB717Sa.jpg', 'https://image.tmdb.org/t/p/original/syVAWAnY6fTBDDFntHsM8vFjKex.jpg', 'The film revolves around a local street-racer who partners with a rich and arrogant business associate, only to find himself framed by his colleague and sent to prison. After he gets out, he joins a New York-to-Los Angeles race to get revenge. But when the ex-partner learns of the scheme, he puts a massive bounty on the racer''s head, forcing him to run a cross-country gauntlet of illegal racers in all manner of supercharged vehicles.', NULL, NULL, 10.363, 6.444, 0, 1.03, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9989, 9208, 'tt0115759', NULL, 'Broken Arrow', 'Broken Arrow', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/iBPMwYYJFvdCBkXrwV75peo5Lz2.jpg', 'https://image.tmdb.org/t/p/original/446lXnrT0vSIkeClW8bCN8KrnxN.jpg', 'When rogue stealth-fighter pilot Vic Deakins deliberately drops off the radar while on maneuvers, the Air Force ends up with two stolen nuclear warheads -- and Deakins''s co-pilot, Riley Hale, is the military''s only hope for getting them back. Traversing the deserted canyons of Utah, Hale teams with park ranger Terry Carmichael to put Deakins back in his box.', NULL, NULL, 6.9793, 6.069, 0, 1.02, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9990, 267193, 'tt3381008', NULL, 'Grimsby', 'Grimsby', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/2jQGFmShpdflApc5oidJZ97m1d1.jpg', 'https://image.tmdb.org/t/p/original/tt0QtXBnUBq3Lt4WSkcORyAJ6YP.jpg', 'Wrongfully accused and on the run, a top MI6 assassin joins forces with his long-lost, football hooligan brother to save the world from a sinister plot.', NULL, NULL, 7.8426, 5.947, 0, 1.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
