INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10005, 502216, 'tt0809927', NULL, 'Karas: The Prophecy', '鴉－KARAS－', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/qaOXBrYoPhXfzF1OqkiJ8yBSqTU.jpg', 'https://image.tmdb.org/t/p/original/shiQSjqI1ufmbF30TRxCpxWBsmi.jpg', 'Tokyo: a city populated by both humans and ghostly beings. They exist in both dimensions, seen and unseen: spirits, apparitions, demons. The balance between these two dimensions has long been upheld by the city''s guardian crow Karas and his masters. But that balance has been thrown into disarray as Eko, a former Karas, has attempted to seize power and bring order to the streets through force. The entity Yurine, who represents the will of the people, stands in his way with her newly risen Karas. Now an ageless battle stretching across both dimensions and killing humans and spirits alike is in progress. Karas is humanity''s last hope.', NULL, NULL, 1.7006, 6.13, 0, 2.03, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
