INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10058, NULL, NULL, 3084, 'Cry of Fear', 'Cry of Fear', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6m51.jpg', NULL, 'Cry of Fear is a single-player, horror modification for Half-Life 1 that brings you all the horrors you have always been afraid of.
This is a free total converstion of Half-Life 1, which means none of the assets from Half-Life 1 have been used in this mod or any files from other people, it is a totally unique experience. Everything is made exclusively by Team Psykskallar, the Cry of Fear developers.', 'https://www.igdb.com/games/cry-of-fear', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.02, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10059, NULL, NULL, 298775, 'We''re Closed Sorry', 'We''re Closed Sorry', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ipo.jpg', NULL, 'We''re closed Sorry is a metroidvania in which the player controls both a titular hero traversing the interior of a retro supermarket store and the owner of the store. Immerse in an action-adventure combating bugs, finding secrets, and becoming a dreamt hero.

As the owner of the store, the game only begins when you close your shop allowing all creepy things and bugs to lurk in the dark terrorizing the store and your products.', 'https://www.igdb.com/games/were-closed-sorry', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.02, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10060, NULL, NULL, 121084, 'In Sound Mind', 'In Sound Mind', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3p6y.jpg', NULL, 'In Sound Mind is an imaginative first-person psychological horror with frenetic puzzles, unique boss fights, and original music. Journey within the inner workings of the one place you can’t seem to escape - your own mind.', 'https://www.igdb.com/games/in-sound-mind', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Nintendo Switch"]', NULL, NULL, 0, 1.02, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10061, 1649, 'tt0101452', NULL, 'Bill & Ted''s Bogus Journey', 'Bill & Ted''s Bogus Journey', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/tldtDfLnPFOtTWp758EmIP2Hbz5.jpg', 'https://image.tmdb.org/t/p/original/4PMSgLOzPFgyzARQBhhX4vS9oOW.jpg', 'Amiable slackers Bill and Ted are once again roped into a fantastical adventure when De Nomolos, a villain from the future, sends evil robot duplicates of the two lads to terminate and replace them. The robot doubles actually succeed in killing Bill and Ted, but the two are determined to escape the afterlife, challenging the Grim Reaper to a series of games in order to return to the land of the living.', NULL, NULL, 3.7078, 6.299, 0, 11.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
