INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10081, 133557, 'tt2132485', NULL, 'The Girl', 'The Girl', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/3LKSvrDqOWGvbE3JPleBrQeo0jO.jpg', 'https://image.tmdb.org/t/p/original/hA9PSz23iaYt0ZtPC45UnROT6SA.jpg', 'Director Alfred Hitchcock is revered as one of the greatest creative minds in the history of cinema. Known for his psychological thrillers, Hitchcock’s leading ladies were cool, beautiful and preferably blonde. One such actress was Tippi Hedren, an unknown fashion model given her big break when Hitchcock’s wife saw her on a TV commercial. Brought to Universal Studios, Hedren was shocked when the director, at the peak of his career, quickly cast her to star in his next feature, 1963’s The Birds. Little did Hedren know that as ambitious and terrifying as the production would be to shoot, the most daunting aspect of the film ended up coming from behind the camera.', NULL, NULL, 1.6063, 6.139, 0, 1.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
