INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10111, 527641, 'tt6472976', NULL, 'Five Feet Apart', 'Five Feet Apart', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/kreTuJBkUjVWePRfhHZuYfhNE1T.jpg', 'https://image.tmdb.org/t/p/original/cYdHaKx6Ihj1BIvbxpCxIGXfZ02.jpg', 'Seventeen-year-old Stella spends most of her time in the hospital as a cystic fibrosis patient. Her life is full of routines, boundaries and self-control — all of which get put to the test when she meets Will, an impossibly charming teen who has the same illness. There''s an instant flirtation, though restrictions dictate that they must maintain a safe distance between them. As their connection intensifies, so does the temptation to throw the rules out the window and embrace that attraction.', NULL, NULL, 10.3711, 8.215, 0, 3.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10112, 330916, 'tt3863484', NULL, 'King Jack', 'King Jack', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/mguFl12DkIljwp8Kal04q04FeLw.jpg', 'https://image.tmdb.org/t/p/original/bBFOFiL40TEv5fZ9waigXmoR6Yr.jpg', 'Growing up in a rural town filled with violent delinquents, Jack has learned to do what it takes to survive, despite having an oblivious mother and no father. After his aunt falls ill and a younger cousin comes to stay with him, the hardened 15-year-old discovers the importance of friendship, family, and looking for happiness even in the most desolate of circumstances.', NULL, NULL, 0.9817, 6.341, 0, 3.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
