INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10163, 436274, 'tt6097798', NULL, 'Radius', 'Radius', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/3BHYW2Wlcu9ES41Y4OTeSgkhYkD.jpg', 'https://image.tmdb.org/t/p/original/46wTOIqhV94OuFp2uTnbw4emKZR.jpg', 'Liam wakes from a car crash with no memory of who he is. As he makes his way into town to look for help, he finds only dead bodies, all with strange pale eyes. Liam''s first assessment is that a virus is present in the air, but he soon discovers the horrible truth: anyone who comes within a 50-foot radius of him dies instantly.', NULL, NULL, 3.8585, 6.484, 0, 9.51, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
