INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10165, 51321, 'tt0095853', NULL, 'Permanent Record', 'Permanent Record', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/AsoyWPJwtuRJuHyMhXpcsK0XrbX.jpg', 'https://image.tmdb.org/t/p/original/disE4kPp6jkIR8MJhVsdYuKyv3q.jpg', 'David Sinclair seems to have everything going for him: he''s smart, musically talented, and very successful. To top off his senior year in high school, his band is trying to get a recording session. Therefore, David''s suicide leaves everyone, especially his best friend and bandmate, Chris, with a lot of questions.', NULL, NULL, 1.9024, 6.37, 0, 1.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
