INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10169, 878214, 'tt12991200', NULL, 'Drinkwater', 'Drinkwater', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/zfeHyfkG5OxAC0wlcbh8cPGIFlt.jpg', 'https://image.tmdb.org/t/p/original/nIzAK2g8yZTNSM0yfzlceqc11sV.jpg', 'In small-town British Columbia, Canada, awkward teen Mike Drinkwater has trouble fitting in and is bullied by his antagonist and rival: wealthy school jock, Luke Ryan. While Mike''s offbeat father, Hank, spends more time defrauding the government than being a role model; Hank is dealing with his own longstanding condemnation by Luke''s father Wesley Ryan, which seems to fuel Luke''s hostility towards Mike. Enter Wallace, a young girl from the United States who is adjusting to life in a new place while recovering from her own personal tragedy. Wallace''s strength of character helps transform her life and the lives of the people around her.', NULL, NULL, 0.8438, 5.889, 0, 9.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
