INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10175, 1205336, 'tt27469154', NULL, 'Leviticus 20:13', 'Leviticus 20:13', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/cZ4WwW1WTkjrpw705nCM4at6uYo.jpg', 'https://image.tmdb.org/t/p/original/pQNbAMpVAXpSzs9s5pBQTtP3r88.jpg', 'This is the story of Damián, an obsessed 30-year-old young man, who has suffered all his life from the sexual abuse of his childhood caused by several priests from his school. These traumas from the past worsen with his small addiction to alcohol, which he tries to hide in his immediate surroundings. A night of hunting for the gay-friendly venues in the city. Of the revenge that he has simmered throughout a lifetime darkened by the abuse suffered in his childhood. Of a bloody and purifying ritual. Revenge or justice?', NULL, NULL, 0.5201, 0.0, 0, 9.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10176, NULL, NULL, 28552, 'Far Cry 5', 'Far Cry 5', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21a6.jpg', NULL, 'Welcome to Hope County, Montana, land of the free and the brave, but also home to a fanatical doomsday cult known as The Project at Eden’s Gate that is threatening the community''s freedom. Stand up to the cult’s leader, Joseph Seed and the Heralds, and spark the fires of resistance that will liberate the besieged community.

In this expansive world, your limits and creativity will be tested against the biggest and most ruthless baddest enemy Far Cry has ever seen. It’ll be wild and it’ll get weird, but as long as you keep your wits about you, the residents of Hope County can rest assured knowing you’re their beacon of hope.', 'https://www.igdb.com/games/far-cry-5', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, NULL, 0, 8.01, '2026-08-17 16:08:12', '2026-08-17 16:08:12');
