UPDATE "recommendations" SET "tmdb_id"=37735, "imdb_id"='tt1282140', "igdb_id"=NULL, "title"='Easy A', "original_title"='Easy A', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/v5f1qO6NJnxWgONgkYg21TW39DT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/30rvmoEBqovm723agDJ3QddWXcY.jpg', "overview"='Olive, an average high school student, sees her below-the-radar existence turn around overnight once she decides to use the school''s gossip grapevine to advance her social standing. Now her classmates are turning against her and the school board is becoming concerned, including her favorite teacher and the distracted guidance counselor. With the support of her hilariously idiosyncratic parents and a little help from a long-time crush, Olive attempts to take on her notorious new identity and crush the rumor mill once and for all.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.2755, "vote_average"=6.8, "is_ambiguous"=0, "evidence_score"=14.455, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=654;
UPDATE "recommendations" SET "tmdb_id"=10096, "imdb_id"='tt0337563', "igdb_id"=NULL, "title"='13 Going on 30', "original_title"='13 Going on 30', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/iNZdSIfhSCMtRILDNyhLn8UKeSG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ld7UTOGzZSxIMbuYsb6eQ6QdN4h.jpg', "overview"='After total humiliation at her thirteenth birthday party, Jenna Rink wants to just hide until she''s thirty. Thanks to some magic wishing dust, Jenna''s prayer has been answered. With a knockout body, a fabulous wardrobe, an athlete boyfriend, a dream job, and superstar friends, this can''t be a better life. But soon Jenna realizes that adult life isn’t as easy as she hoped for.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.9045, "vote_average"=6.777, "is_ambiguous"=0, "evidence_score"=2.01755555555555545e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=667;
UPDATE "recommendations" SET "tmdb_id"=634, "imdb_id"='tt0243155', "igdb_id"=NULL, "title"='Bridget Jones''s Diary', "original_title"='Bridget Jones''s Diary', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/olMTi7uCaec9Yr3Ar07D2SIja1G.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9rSpxsMhG1FnFtUDdvSAXdtLtb3.jpg', "overview"='Bridget Jones is an average woman struggling against expectations. As a New Year''s resolution, Bridget decides to take control of her life, starting by keeping a diary in which she will always tell the complete truth. Her charming boss takes an interest in her, and she cannot stop running into a rather disagreeable acquaintance whom Bridget cannot help finding quietly attractive.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.5575, "vote_average"=6.742, "is_ambiguous"=0, "evidence_score"=8.285, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=673;
UPDATE "recommendations" SET "tmdb_id"=10564, "imdb_id"='tt0198021', "igdb_id"=NULL, "title"='Where the Heart Is', "original_title"='Where the Heart Is', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/3iyT5W3PjDKMKVS1vfAnDLeSXh2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ahGSlXunI3Aa0MV4IXlpjYVSVWI.jpg', "overview"='Novalee Nation is a 17-year-old Tennessee transient who has to grow up in a hurry when she''s left pregnant and abandoned by her boyfriend on a roadside, and takes refuge in the friendly aisles of Wal-Mart. Eventually, some eccentric but kindly strangers ''adopt'' Novalee and her infant daughter, helping them buck the odds and build a new life.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6513, "vote_average"=7.1, "is_ambiguous"=0, "evidence_score"=9.17833333333333278e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=675;
