UPDATE "recommendations" SET "tmdb_id"=560016, "imdb_id"='tt9214772', "igdb_id"=NULL, "title"='Monkey Man', "original_title"='Monkey Man', "media_type"='movie', "release_year"=2024, "poster_url"='https://image.tmdb.org/t/p/w500/4lhR4L2vzzjl68P1zJyCH755Oz4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9NSXdVHeSfSHUv49OzLispFcpz1.jpg', "overview"='Kid is an anonymous young man who ekes out a meager living in an underground fight club where, night after night, wearing a gorilla mask, he is beaten bloody by more popular fighters for cash. After years of suppressed rage, Kid discovers a way to infiltrate the enclave of the city’s sinister elite. As his childhood trauma boils over, his mysteriously scarred hands unleash an explosive campaign of retribution to settle the score with the men who took everything from him.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.043, "vote_average"=6.85, "is_ambiguous"=0, "evidence_score"=5.76, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1031;
