UPDATE "recommendations" SET "tmdb_id"=10490, "imdb_id"='tt0157503', "igdb_id"=NULL, "title"='Drop Dead Gorgeous', "original_title"='Drop Dead Gorgeous', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/iMMvFvHhURa4cWv6CxhpwIDjme2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xXSDhhyC853VgF7OCDKpXKeA5Md.jpg', "overview"='In a small Minnesota town, the annual beauty pageant is being covered by a TV crew. Former winner Gladys Leeman wants to make sure her daughter follows in her footsteps; explosions, falling lights, and trailer fires prove that. As the Leemans are the richest family in town, the police are pretty relaxed about it all. Despite everything, main rival (but sweet) Amber Atkins won''t give up without a fight.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.16, "vote_average"=6.457, "is_ambiguous"=0, "evidence_score"=1.72357142857142875e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1041;
UPDATE "recommendations" SET "tmdb_id"=47866, "imdb_id"='tt0104321', "igdb_id"=NULL, "title"='Gas Food Lodging', "original_title"='Gas Food Lodging', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/4klEYvGDHmv89NQRfAaDc8qHncs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/byckFRHkQnXZezIGjamsYTjCvlb.jpg', "overview"='Nora, a single mother raising two teenage daughters, Shade and Trudi, waits tables at a truck-stop diner in a small New Mexico town. The beautiful and rebellious Trudi drops out of school and gets a job alongside Nora, while the younger Shade whittles away her time at Spanish movie matinees. Their lives are turned upside down when Trudi becomes pregnant and the girls'' absent father returns.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.207, "vote_average"=6.264, "is_ambiguous"=0, "evidence_score"=6.5175, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1042;
UPDATE "recommendations" SET "tmdb_id"=570, "imdb_id"='tt0243255', "igdb_id"=NULL, "title"='Fat Girl', "original_title"='À ma sœur !', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/afzbY1h7huuxlITigPfcyQSkqLs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gk7k11v0G9QiSEpDR5fhr6Ihkwa.jpg', "overview"='Anaïs is twelve and bears the weight of the world on her shoulders. She watches her older sister, Elena, whom she both loves and hates. Elena is fifteen and devilishly beautiful. Neither more futile, nor more stupid than her younger sister, she cannot understand that she is merely an object of desire. And, as such, she can only be taken. Or had. Indeed, this is the subject: a girl''s loss of virginity. And, that summer, it opens a door to tragedy.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.414, "vote_average"=6.183, "is_ambiguous"=0, "evidence_score"=6.62, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1043;
