UPDATE "recommendations" SET "tmdb_id"=133121, "imdb_id"='tt1753496', "igdb_id"=NULL, "title"='Resident Evil: Damnation', "original_title"='バイオハザード ダムネーション', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/zkHSURVCrt7rpvDDgUXO75CV1v4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xbjOkrAaT4CAIrNJ38oQSBomHvg.jpg', "overview"='U.S. federal agent Leon S. Kennedy sneaks into the "East Slavic Republic" to verify rumors that Bio-Organic Weapons (BOWs) are being used in the country''s civil war, which the U.S. and Russia are making preparations to jointly intervene in. Right after his infiltration, the U.S. government orders him to leave immediately. Determined to uncover the truth, Leon ignores the order and enters the battlefield to end the chain of tragedies caused by the BOWs.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.6379, "vote_average"=6.896, "is_ambiguous"=0, "evidence_score"=6.35, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1104;
