UPDATE "recommendations" SET "tmdb_id"=8619, "imdb_id"='tt0311113', "igdb_id"=NULL, "title"='Master and Commander: The Far Side of the World', "original_title"='Master and Commander: The Far Side of the World', "media_type"='movie', "release_year"=2003, "poster_url"='https://image.tmdb.org/t/p/w500/s1cVTQEZYn4nSjZLnFbzLP0j8y2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/zMHyNxNt4zhL939XX8QLBW3gWfu.jpg', "overview"='After an abrupt and violent encounter with a French warship inflicts severe damage upon his ship, a captain of the British Royal Navy begins a chase over two oceans to capture or destroy the enemy, though he must weigh his commitment to duty and ferocious pursuit of glory against the safety of his devoted crew, including the ship''s thoughtful surgeon, his best friend.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.3803, "vote_average"=7.199, "is_ambiguous"=0, "evidence_score"=23.80125, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1432;
UPDATE "recommendations" SET "tmdb_id"=8066, "imdb_id"='tt0371257', "igdb_id"=NULL, "title"='Stay', "original_title"='Stay', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/nrLZVP8jG0KBcabahRPp6UP7Oy2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/eUNQJ0XKHoGDDQzj1Y4WhE5zAFJ.jpg', "overview"='Psychiatrist Sam Foster has a new patient, Henry Letham, who claims to be suicidal. In trying to diagnose him, Sam visits Henry''s prior therapist and also finds Henry''s mother -- even though Henry has said that he murdered both of his parents. As reality starts to contradict fact, Sam spirals into an unstable mental state. Then he finds a clue as to how and when Henry may try to kill himself, and races to try to stop him.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.2007, "vote_average"=6.639, "is_ambiguous"=0, "evidence_score"=23.4585, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1446;
UPDATE "recommendations" SET "tmdb_id"=10836, "imdb_id"='tt0264508', "igdb_id"=NULL, "title"='Dagon', "original_title"='Dagon', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/8S648eMKObi8ERFS7cSYDocxSaZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nO8lpaJLo1UVIXL7eM5ewwudvtY.jpg', "overview"='A boating accident off the coast of Spain sends Paul and his girlfriend Barbara to the decrepit fishing village of Imboca. As night falls, people start to disappear and things not quite human start to appear. Paul is pursued by the entire town. Running for his life, he uncovers Imboca''s secret..they worship Dagon, a monstrous god of the sea...and Dagon''s unholy offspring are on the loose...', "external_url"=NULL, "platforms"=NULL, "popularity"=4.0137, "vote_average"=6.123, "is_ambiguous"=0, "evidence_score"=1.28939999999999983e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1447;
UPDATE "recommendations" SET "tmdb_id"=3558, "imdb_id"='tt0172493', "igdb_id"=NULL, "title"='Girl, Interrupted', "original_title"='Girl, Interrupted', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/dOBdatHIVppvmRFw2z7bf9VKJr9.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jDePFWhpfkY4GJm41qiRffJ0NGq.jpg', "overview"='Set in the changing world of the late 1960s, Susanna Kaysen''s prescribed "short rest" from a psychiatrist she had met only once becomes a strange, unknown journey into Alice''s Wonderland, where she struggles with the thin line between normal and crazy. Susanna soon realizes how hard it is to get out once she has been committed, and she ultimately has to choose between the world of people who belong inside or the difficult world of reality outside.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.3041, "vote_average"=7.56, "is_ambiguous"=0, "evidence_score"=3.20614285714285713e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1448;
