UPDATE "recommendations" SET "tmdb_id"=15058, "imdb_id"='tt0378793', "igdb_id"=NULL, "title"='Speak', "original_title"='Speak', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/oRjQJG2PziTl2bUvzUCFS16ncfj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9J759jTIcQhmeeiD5bDuXI7iOoC.jpg', "overview"='Freshman high-school student Melinda has refused to speak ever since she called the cops on a popular summer party. With her old friends snubbing her for being a rat, and her parents too busy to notice her troubles, she folds into herself, trying to hide her secret: that star senior Andy raped her at the party. But Melinda does manage to find solace in her art class headed by Mr. Freeman.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.4011, "vote_average"=7.078, "is_ambiguous"=0, "evidence_score"=11.1325, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=1456;
