UPDATE "recommendations" SET "tmdb_id"=840889, "imdb_id"='tt14852624', "igdb_id"=NULL, "title"='Stopmotion', "original_title"='Stopmotion', "media_type"='movie', "release_year"=2024, "poster_url"='https://image.tmdb.org/t/p/w500/kWzWZEctPcZ0dATbtcYy6lIJgGj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/shS6buEDnEDoHTdLbGzCoDIZ9ur.jpg', "overview"='Ella Blake, a stop-motion animator struggling to control her demons after the loss of her overbearing mother, embarks upon the creation of a film that becomes the battleground for her sanity. As Ella’s mind starts to fracture, the characters in her project take on a life of their own.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.3158, "vote_average"=6.123, "is_ambiguous"=0, "evidence_score"=7.68500000000000049e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=2245;
UPDATE "recommendations" SET "tmdb_id"=286565, "imdb_id"='tt3622592', "igdb_id"=NULL, "title"='Paper Towns', "original_title"='Paper Towns', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/lVW67w7eWwmBhbBCc4f983pO8m6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mwoIzHsliirmS0IlSrf2DvVouid.jpg', "overview"='Quentin Jacobsen has spent a lifetime loving the magnificently adventurous Margo Roth Spiegelman from afar. So when she cracks open a window and climbs back into his life dressed like a ninja and summoning him for an ingenious campaign of revenge, he follows. After their all-nighter ends and a new day breaks, Quentin arrives at school to discover that Margo, always an enigma, has now become a mystery. But Quentin soon learns that there are clues, and they''re for him. Urged down a disconnected path, the closer Quentin gets, the less he sees of the girl he thought he knew.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.7914, "vote_average"=6.155, "is_ambiguous"=0, "evidence_score"=1.60566666666666648e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=2254;
