UPDATE "recommendations" SET "tmdb_id"=77174, "imdb_id"='tt1623288', "igdb_id"=NULL, "title"='ParaNorman', "original_title"='ParaNorman', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/9DZPtuYTKYxt6vzHvZ5FLThG4fl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fRhpdmaA1wTAboeiKW2ZHvDezIm.jpg', "overview"='In the town of Blithe Hollow, Norman Babcock can speak to the dead, but no one other than his eccentric new friend believes his ability is real. One day, Norman''s eccentric uncle tells him of a ritual he must perform to protect the town from a curse cast by a witch centuries ago.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.708, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=13.009, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=2277;
