UPDATE "recommendations" SET "tmdb_id"=94997, "imdb_id"='tt11198330', "igdb_id"=NULL, "title"='House of the Dragon', "original_title"='House of the Dragon', "media_type"='tv', "release_year"=2022, "poster_url"='https://image.tmdb.org/t/p/w500/7V0Ebks0GgpKvQ7QbLAIdX5dos4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/577eXC8wFQT0eUrJcgznSiFPRmk.jpg', "overview"='The Targaryen dynasty is at the absolute apex of its power, with more than 15 dragons under their yoke. Most empires crumble from such heights. In the case of the Targaryens, their slow fall begins when King Viserys breaks with a century of tradition by naming his daughter Rhaenyra heir to the Iron Throne. But when Viserys later fathers a son, the court is shocked when Rhaenyra retains her status as his heir, and seeds of division sow friction across the realm.', "external_url"=NULL, "platforms"=NULL, "popularity"=343.2786, "vote_average"=8.386, "is_ambiguous"=0, "evidence_score"=7.6899999999999995e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=2308;
