UPDATE "recommendations" SET "tmdb_id"=54671, "imdb_id"='tt2628232', "igdb_id"=NULL, "title"='Penny Dreadful', "original_title"='Penny Dreadful', "media_type"='tv', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/hQSdrXBYTbLGHYDIseHkBOPXTgL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/32iacqVElB91YZKl9Ky3QEEkXtH.jpg', "overview"='Some of literature''s most terrifying characters, including Dr. Frankenstein, Dorian Gray, and iconic figures from the novel Dracula are lurking in the darkest corners of Victorian London. Penny Dreadful is a frightening psychological thriller that weaves together these classic horror origin stories into a new adult drama.', "external_url"=NULL, "platforms"=NULL, "popularity"=13.5137, "vote_average"=7.8, "is_ambiguous"=0, "evidence_score"=2.23690476190476204e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=2337;
