UPDATE "recommendations" SET "tmdb_id"=82682, "imdb_id"='tt1321870', "igdb_id"=NULL, "title"='Gangster Squad', "original_title"='Gangster Squad', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/wAuQNTBFBu2yXZsX6yLhUPiwTlW.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cdd4S09XxLLvp6IRN4PQamPAXL6.jpg', "overview"='Los Angeles, 1949. Ruthless, Brooklyn-born mob king Mickey Cohen runs the show in this town, reaping the ill-gotten gains from the drugs, the guns, the prostitutes and — if he has his way — every wire bet placed west of Chicago. And he does it all with the protection of not only his own paid goons, but also the police and the politicians who are under his control. It’s enough to intimidate even the bravest, street-hardened cop… except, perhaps, for the small, secret crew of LAPD outsiders led by Sgt. John O’Mara and Jerry Wooters who come together to try to tear Cohen’s world apart.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.8111, "vote_average"=6.381, "is_ambiguous"=0, "evidence_score"=7.9275, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=2355;
UPDATE "recommendations" SET "tmdb_id"=9778, "imdb_id"='tt0240890', "igdb_id"=NULL, "title"='Serendipity', "original_title"='Serendipity', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/4jS66Qmq2Ru5S2YzHVknGd4xJyT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/sBecqcXgrLRiwufYr6apGnYA70k.jpg', "overview"='Although strangers Sara and Jonathan are both already in relationships, they realize they have genuine chemistry after a chance encounter – but part company soon after. Years later, they each yearn to reunite, despite being destined for the altar. But to give true love a chance, they have to find one another again.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.4397, "vote_average"=6.965, "is_ambiguous"=0, "evidence_score"=1.28372727272727278e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=2356;
UPDATE "recommendations" SET "tmdb_id"=829, "imdb_id"='tt0071315', "igdb_id"=NULL, "title"='Chinatown', "original_title"='Chinatown', "media_type"='movie', "release_year"=1974, "poster_url"='https://image.tmdb.org/t/p/w500/kZRSP3FmOcq0xnBulqpUQngJUXY.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pyvkujOZ5qvY2NlQVC71flfgVWE.jpg', "overview"='Private eye Jake Gittes lives off of the murky moral climate of sunbaked, pre-World War II Southern California. Hired by a beautiful socialite to investigate her husband''s extra-marital affair, Gittes is swept into a maelstrom of double dealings and deadly deceits, uncovering a web of personal and political scandals that come crashing together.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.0, "vote_average"=7.904, "is_ambiguous"=0, "evidence_score"=2.48359090909090909e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-17 16:08:12' WHERE "id"=2367;
