UPDATE "recommendations" SET "tmdb_id"=14161, "imdb_id"='tt1190080', "igdb_id"=NULL, "title"='2012', "original_title"='2012', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/zaqam2RNscH5ooYFWInV6hjx6y5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/x9GeCXTGiPcmQcCsd1yzbNnx3up.jpg', "overview"='Dr. Adrian Helmsley, part of a worldwide geophysical team investigating the effect on the earth of radiation from unprecedented solar storms, learns that the earth''s core is heating up. He warns U.S. President Thomas Wilson that the crust of the earth is becoming unstable and that without proper preparations for saving a fraction of the world''s population, the entire race is doomed. Meanwhile, writer Jackson Curtis stumbles on the same information. While the world''s leaders race to build "arks" to escape the impending cataclysm, Curtis struggles to find a way to save his family. Meanwhile, volcanic eruptions and earthquakes of unprecedented strength wreak havoc around the world.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.0514, "vote_average"=5.9, "is_ambiguous"=0, "evidence_score"=9.58857142857142896e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-17 16:08:12' WHERE "id"=3370;
UPDATE "recommendations" SET "tmdb_id"=8007, "imdb_id"='tt0159273', "igdb_id"=NULL, "title"='Behind Enemy Lines', "original_title"='Behind Enemy Lines', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/fZReMWU3zszvaktDUqOoWCzHssZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lEdy2A62qCwJPffMLVyByRxUpfd.jpg', "overview"='While flying a routine reconnaissance mission over Bosnia, fighter pilot Lt. Chris Burnett photographs something he wasn''t supposed to see and gets shot down behind enemy lines, where he must outrun an army led by a ruthless Serbian general. With time running out and a deadly tracker on his trail, Burnett''s commanding officer, Admiral Reigart, decides to risk his career and launch a renegade rescue mission to save his life.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3632, "vote_average"=6.441, "is_ambiguous"=0, "evidence_score"=1.00316666666666662e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-17 16:08:12' WHERE "id"=3384;
