UPDATE "recommendations" SET "tmdb_id"=31225, "imdb_id"='tt0100332', "igdb_id"=NULL, "title"='Paris Is Burning', "original_title"='Paris Is Burning', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/90rCWH41mj9hjHUEy2SOHfuAOl3.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8yJg7SOv0hbuOYhFwq3FW8GajuM.jpg', "overview"='Where does voguing come from, and what, exactly, is throwing shade? This landmark documentary provides a vibrant snapshot of the 1980s through the eyes of New York City''s African American and Latinx Harlem drag-ball scene. Made over seven years, PARIS IS BURNING offers an intimate portrait of rival fashion "houses," from fierce contests for trophies to house mothers offering sustenance in a world rampant with homophobia, transphobia, racism, AIDS, and poverty. Featuring legendary voguers, drag queens, and trans women — including Willi Ninja, Pepper LaBeija, Dorian Corey, and Venus Xtravaganza.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.6079, "vote_average"=8.014, "is_ambiguous"=0, "evidence_score"=9.02, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-17 16:08:12' WHERE "id"=4485;
