UPDATE "recommendations" SET "tmdb_id"=16660, "imdb_id"='tt1992935', "igdb_id"=NULL, "title"='Mononoke', "original_title"='モノノ怪', "media_type"='tv', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/r3S04UDFVaDRC6fOSjLfvrDhpvd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1K0xW8RtPzACZ2Tu42H9R3OlGEw.jpg', "overview"='The Medicine Seller is a deadly and mysterious master of the occult who travels across feudal Japan in search of malevolent spirits called mononoke to slay. When he locates one of these spirits, he cannot simply kill it; he must first learn its Form, its Truth, and its Reason in order to wield the mighty Exorcism Sword and fight against it. He must begin his strange exorcisms with intense psychological analysis and careful investigative work—an extremely dangerous step, as he must first confront and learn about the mononoke before he even has the means to defeat it.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.9274, "vote_average"=8.006, "is_ambiguous"=0, "evidence_score"=12.22, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-17 16:08:12' WHERE "id"=5031;
