UPDATE "recommendations" SET "tmdb_id"=13245, "imdb_id"='tt0285441', "igdb_id"=NULL, "title"='Atanarjuat: The Fast Runner', "original_title"='ᐊᑕᓈᕐᔪᐊᑦ', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/jSGiFOTwosoiAAXLTLHtzMUCVUN.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/q3XAe77oga8zCH8G6d8T4izEPZ6.jpg', "overview"='Based on a local legend and set in an unknown era, it deals with universal themes of love, possessiveness, family, jealousy and power. Beautifully shot, and acted by Inuit people, it portrays a time when people fought duels by taking turns to punch each other until one was unconscious, made love on the way to the caribou hunt, ate walrus meat and lit their igloos with seal-oil lamps.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9513, "vote_average"=6.797, "is_ambiguous"=0, "evidence_score"=6.06666666666666643e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-17 16:08:12' WHERE "id"=6973;
