UPDATE "recommendations" SET "tmdb_id"=57829, "imdb_id"='tt1324055', "igdb_id"=NULL, "title"='The Mill and the Cross', "original_title"='Młyn i krzyż', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/3IKLkxxXf38C2hY9ONi6Lvlz1qM.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/osjuwnDnIGW0MpHJgcSRBUjPsZ6.jpg', "overview"='What would it be like to step inside a great work of art, have it come alive around you, and even observe the artist as he sketches the very reality you are experiencing? From Lech Majewski, one of Poland''s most acclaimed filmmakers, The Mill and the Cross is a cinematic re-staging of Pieter Bruegel''s masterpiece "Procession to Calvary," presented alongside the story of its creation.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.4734, "vote_average"=6.353, "is_ambiguous"=0, "evidence_score"=6.5175, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-17 16:08:12' WHERE "id"=7005;
UPDATE "recommendations" SET "tmdb_id"=568467, "imdb_id"='tt7983894', "igdb_id"=NULL, "title"='Ammonite', "original_title"='Ammonite', "media_type"='movie', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/5lx4pUHWZoOKJWsVsvurRRNW9FK.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/23wCZgZ3mDtATocmy1lXNLM7pyx.jpg', "overview"='In 1840s England, palaeontologist Mary Anning and a young woman sent by her husband to convalesce by the sea develop an intense relationship. Despite the chasm between their social spheres and personalities, Mary and Charlotte discover they can each offer what the other has been searching for: the realisation that they are not alone. It is the beginning of a passionate and all-consuming love affair that will defy all social bounds and alter the course of both lives irrevocably.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.1544, "vote_average"=6.899, "is_ambiguous"=0, "evidence_score"=5.8275, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-17 16:08:12' WHERE "id"=7014;
