UPDATE "recommendations" SET "tmdb_id"=617505, "imdb_id"='tt10682266', "igdb_id"=NULL, "title"='Hubie Halloween', "original_title"='Hubie Halloween', "media_type"='movie', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/dbhC6qRydXyRmpUdcl9bL9rARya.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/aOeshAxAhiDVIiHsXVFmF6bgclh.jpg', "overview"='Hubie Dubois, despite his devotion to his hometown of Salem, Massachusetts (and its legendary Halloween celebration), is a figure of mockery for kids and adults alike. But this year, something really is going bump in the night, and it’s up to Hubie to save Halloween.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6414, "vote_average"=5.886, "is_ambiguous"=0, "evidence_score"=8.52571428571428668e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-17 16:08:12' WHERE "id"=7109;
UPDATE "recommendations" SET "tmdb_id"=5055, "imdb_id"='tt0052080', "igdb_id"=NULL, "title"='Ashes and Diamonds', "original_title"='Popiół i diament', "media_type"='movie', "release_year"=1958, "poster_url"='https://image.tmdb.org/t/p/w500/nE8aqRvVnRQEqskiarnFhdJdk8g.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1QlZ3Kge4bCH01V3VibxckeVIiu.jpg', "overview"='A young academy soldier, Maciek Chelmicki, is ordered to shoot the secretary of the KW PPR. A coincidence causes him to kill someone else. Meeting face to face with his victim, he gets a shock. He faces the necessity of repeating the assassination.  He meets Krystyna, a girl working as a barmaid in the restaurant of the "Monopol" hotel. His affection for her makes him even more aware of the senselessness of killing at the end of the war. Loyalty to the oath he took, and thus the obligation to obey the order, tips the scales.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9529, "vote_average"=7.412, "is_ambiguous"=0, "evidence_score"=6.03333333333333321e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-17 16:08:12' WHERE "id"=7116;
UPDATE "recommendations" SET "tmdb_id"=789, "imdb_id"='tt0060802', "igdb_id"=NULL, "title"='Closely Watched Trains', "original_title"='Ostře sledované vlaky', "media_type"='movie', "release_year"=1966, "poster_url"='https://image.tmdb.org/t/p/w500/oKiOhsSRWO6fRqxtvda8WuCiXBm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pe2APM7NsJXfNRfq2cUWdc0dRbQ.jpg', "overview"='At a village railway station in occupied Czechoslovakia, a bumbling dispatcher’s apprentice longs to liberate himself from his virginity. Oblivious to the war and the resistance that surrounds him, this young man embarks on a journey of sexual awakening and self-discovery, encountering a universe of frustration, eroticism, and adventure within his sleepy backwater depot.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.0728, "vote_average"=7.224, "is_ambiguous"=0, "evidence_score"=6.26500000000000056e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-17 16:08:12' WHERE "id"=7125;
UPDATE "recommendations" SET "tmdb_id"=1778, "imdb_id"='tt0415463', "igdb_id"=NULL, "title"='Zoey 101', "original_title"='Zoey 101', "media_type"='tv', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/3eOM57RTccTSvqcYFhWwm9DAba8.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/92adEq7w76pC5Lry50N0PTsjJ1.jpg', "overview"='Zoey 101 is an American television series which originally aired on Nickelodeon from January 9, 2005 until May 2, 2008. It focuses on the lives of teenager Zoey Brooks and her friends as they attend Pacific Coast Academy, a fictional boarding school in Southern California. It was created by Dan Schneider. It was initially filmed at Pepperdine University in Malibu, California, then at stages in Valencia, California beginning in season 3. It was nominated for an "Outstanding Children''s Program" Emmy in 2005. Zoey 101 was the most expensive production ever for Nickelodeon series, as it was shot completely on location in Malibu. It was also Nickelodeon''s best performance for a series premiere in almost eight years. Despite this, many critics have made negative comments about the show, its setting, and its characters.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.5824, "vote_average"=8.105, "is_ambiguous"=0, "evidence_score"=2.03, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-17 16:08:12' WHERE "id"=7157;
