UPDATE "recommendations" SET "tmdb_id"=4523, "imdb_id"='tt0461770', "igdb_id"=NULL, "title"='Enchanted', "original_title"='Enchanted', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/8KCNzCArLlvLdQoHx6npua2VSVc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/u4UpRDi0w84aNrigr9p049rMHiy.jpg', "overview"='The beautiful princess Giselle is banished by an evil queen from her magical, musical animated land and finds herself in the gritty reality of the streets of modern-day Manhattan. Shocked by this strange new environment that doesn''t operate on a "happily ever after" basis, Giselle is now adrift in a chaotic world badly in need of enchantment. But when Giselle begins to fall in love with a charmingly flawed divorce lawyer who has come to her aid - even though she is already promised to a perfect fairy tale prince back home - she has to wonder: Can a storybook view of romance survive in the real world?', "external_url"=NULL, "platforms"=NULL, "popularity"=10.8646, "vote_average"=6.848, "is_ambiguous"=0, "evidence_score"=2.06, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-17 16:08:12' WHERE "id"=8637;
