UPDATE "recommendations" SET "tmdb_id"=9331, "imdb_id"='tt0109444', "igdb_id"=NULL, "title"='Clear and Present Danger', "original_title"='Clear and Present Danger', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/6xTM8FPxrLRYwz6I3fqtwh7xybs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hEMxuwywh3FmWjhkIrfo57k3M2n.jpg', "overview"='Agent Jack Ryan becomes acting Deputy Director of Intelligence for the CIA when Admiral Greer is diagnosed with cancer. When an American businessman, and friend of the president, is murdered on his yacht, Ryan starts discovering links between the man and drug dealers. As former CIA agent John Clark is sent to Colombia to kill drug cartel kingpins in retaliation, Ryan must fight through multiple cover-ups to figure out what happened and who''s responsible.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6468, "vote_average"=6.7, "is_ambiguous"=0, "evidence_score"=5.02, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-17 16:08:12' WHERE "id"=8744;
