UPDATE "recommendations" SET "tmdb_id"=110971, "imdb_id"='tt10801534', "igdb_id"=NULL, "title"='How To with John Wilson', "original_title"='How To with John Wilson', "media_type"='tv', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/jpHziYpJniprEFDFwMbOHabgnow.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lnnXNSb3Uk9Y4YWF1Rszyt6tzj0.jpg', "overview"='In a uniquely hilarious odyssey of self-discovery and cultural observation, documentary filmmaker and self-described "anxious New Yorker" John Wilson covertly and obsessively films the lives of his fellow New Yorkers while attempting to give everyday advice on relatable topics. The awkward contradictions of modern life are eased by Wilson’s candid, unpolished commentary. Building upon Wilson’s previously released "how to" short films, each episode takes wildly unexpected turns but is grounded in John''s refreshing honesty.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.7102, "vote_average"=8.111, "is_ambiguous"=0, "evidence_score"=6.3125, "created_at"='2026-08-10 02:34:01', "updated_at"='2026-08-17 16:08:12' WHERE "id"=8893;
