UPDATE "recommendations" SET "tmdb_id"=25969, "imdb_id"='tt0112368', "igdb_id"=NULL, "title"='Angus', "original_title"='Angus', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/x1Py4TB8Y0Wx9IZ62derpSDqwjd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qGW0LutVJfqEkBGooJj3w9ngLV8.jpg', "overview"='Angus is a large, pathetic 14-year-old whose thoughts are most often filled with the image of only one girl, Melissa Lefevre. Angus is shy and thinks that he has no chance of ever ''getting'' her. Being especially uncool, he is incredibly surprised (along with the rest of the school) that he is chosen to dance with her at the Winter Ball. The only one not surprised is the cool kid who set him up to fail, but Angus'' best friend is going to help him win the heart of Melissa by developing a new look for him', "external_url"=NULL, "platforms"=NULL, "popularity"=1.5539, "vote_average"=6.6, "is_ambiguous"=0, "evidence_score"=9.04, "created_at"='2026-08-11 02:46:38', "updated_at"='2026-08-17 16:08:12' WHERE "id"=9016;
